// kf_power_tb.v -- workload driver for activity-based power analysis.
//
// Replays a host-transaction script (generated by flow/power.py) on kf_top --
// RTL or a gate-level netlist -- and dumps a VCD of the DUT from the "window"
// command to the end of the script.  OpenSTA then turns the activity into
// power using the extracted parasitics.
//
// Script words (hex, one per line):  {cmd[31:29], addr[28:24], data[23:0]}
//   1  write  DB[addr] <= data
//   2  run    pulse start, wait until ready
//   3  window start dumping activity here
//   4  idle   wait data clock cycles
//   0  end
`timescale 1ns/1ps

module kf_power_tb;
    parameter real PERIOD = 20.0;

    reg         clk = 1'b0, rst_n = 1'b0, start = 1'b0, write = 1'b0;
    reg  [4:0]  dir = 5'd0;
    reg  [23:0] data_in = 24'd0;
    wire        ready;
    wire [23:0] data_out;

    kf_top dut (
        .clk(clk), .rst_n(rst_n), .start(start), .write(write), .dir(dir),
        .data_in(data_in), .ready(ready), .data_out(data_out)
    );

    always #(PERIOD / 2.0) clk = ~clk;

    reg  [31:0]      script [0:65535];
    reg  [8*256-1:0] script_file, vcd_file;
    integer          pc, runs, i;
    real             t0;

    initial begin
        if (!$value$plusargs("script=%s", script_file)) begin
            $display("usage: +script=<file> [+vcd=<file>]");
            $finish;
        end
        if (!$value$plusargs("vcd=%s", vcd_file)) vcd_file = "kf_power.vcd";
        for (i = 0; i < 65536; i = i + 1) script[i] = 32'h0;
        $readmemh(script_file, script);

        repeat (4) @(negedge clk);
        rst_n = 1'b1;
        repeat (4) @(negedge clk);
        runs = 0;
        t0 = -1.0;

        for (pc = 0; script[pc][31:29] != 3'd0; pc = pc + 1) begin
            case (script[pc][31:29])
                3'd1: begin
                    dir     = script[pc][28:24];
                    data_in = script[pc][23:0];
                    write   = 1'b1;
                    @(negedge clk);
                    write   = 1'b0;
                end
                3'd2: begin
                    start = 1'b1;
                    @(negedge clk);
                    start = 1'b0;
                    while (!ready) @(negedge clk);
                    runs = runs + 1;
                end
                3'd3: begin
                    $dumpfile(vcd_file);
                    $dumpvars(0, dut);
                    t0   = $realtime;
                    runs = 0;
                end
                3'd4: repeat (script[pc][23:0]) @(negedge clk);
                default: ;
            endcase
        end
        $display("WINDOW cycles=%0d iterations=%0d", $rtoi(($realtime - t0) / PERIOD), runs);
        $finish;
    end
endmodule
